const body = $json.body || {};
if (typeof body.message !== 'string' || !body.message.trim() || body.message.length > 1000) throw new Error('Invalid message');
const history = (Array.isArray(body.history) ? body.history : []).slice(-4)
 .filter(h => typeof h.message === 'string' && typeof h.reply === 'string')
 .map(h => ({message:h.message.slice(0,1000),reply:h.reply.slice(0,1500)}));
const sources = (Array.isArray(body.sources) ? body.sources : []).slice(0,3)
 .filter(s => Number.isInteger(s.id) && typeof s.excerpt === 'string')
 .map(s => ({id:s.id,title:String(s.title || '').slice(0,200),locator:String(s.locator || '').slice(0,120),excerpt:s.excerpt.slice(0,1800)}));
return [{json:{message:body.message.trim(),history,sources}}];

// Only reviewed excerpts already retrieved by Django for THIS request.
// No SQL access, web browsing, account identifiers or cross-session memory.
const sources = $('Prepare context').first().json.sources;
return JSON.stringify({retrieval:'django_keyword',sources,
 limitation:sources.length ? 'Use only excerpts matching the vehicle and question.' : 'No matching reviewed manual. Ask for model/year; do not invent specifications.'});

if ($json.error) {
 const e = $json.error;
 const code = Number(e.httpCode || e.statusCode || e.status || $json.statusCode);
 const message = typeof e === 'string' ? e : String(e.message || '');
 return [{json:{error:code === 429 || /\b429\b|RESOURCE_EXHAUSTED/.test(message) ? 'rate_limited' : 'unavailable'}}];
}
try {
 const output = typeof $json.output === 'string' ? JSON.parse($json.output) : $json.output;
 if (!output || typeof output.reply !== 'string' || !output.reply.trim() || output.reply.length > 6000 ||
     !Array.isArray(output.citation_ids) || !output.citation_ids.every(Number.isInteger)) throw new Error('Invalid output');
 const allowed = new Set($('Prepare context').first().json.sources.map(s => s.id));
 return [{json:{reply:output.reply.trim(),citation_ids:[...new Set(output.citation_ids)].filter(id => allowed.has(id))}}];
} catch (_) {return [{json:{error:'unavailable'}}];}
